#include<bits/stdc++.h>

using namespace std;

long long takemod(string &s,long long mod){
  long long res=0;
  for(auto &nx : s){
    res*=10;res%=mod;
    res+=(nx-'0');res%=mod;
  }
  return res;
}

int lb(vector<long long> &x,vector<vector<long long>> &lis){
  int l=0,r=lis.size()-1;
  while(l<=r){
    int te=(l+r)/2;
    if(lis[te] < x){l=te+1;}
    else{r=te-1;}
  }
  return l;
}

int ub(vector<long long> &x,vector<vector<long long>> &lis){
  int l=0,r=lis.size()-1;
  while(l<=r){
    int te=(l+r)/2;
    if(lis[te] <= x){l=te+1;}
    else{r=te-1;}
  }
  return l;
}

int main(){
  std::random_device seed_gen;
  std::mt19937_64 engine(seed_gen());

  int n;
  cin >> n;
  int ss=20;
  vector<long long> S;
  for(int i=0;i<ss;i++){
    S.push_back(1000000000+engine()%1000000000);
  }
  vector<vector<long long>> md;
  for(int i=0;i<n;i++){
    string a;
    cin >> a;
    vector<long long> cv;
    for(int j=0;j<ss;j++){
      cv.push_back(takemod(a,S[j]));
    }
    md.push_back(cv);
  }
  sort(md.begin(),md.end());

  long long res=0;
  for(int i=0;i<n;i++){
    for(int j=0;j<n;j++){
      vector<long long> cp;
      for(int k=0;k<ss;k++){
        cp.push_back((md[i][k]*md[j][k])%S[k]);
      }
      res+=ub(cp,md)-lb(cp,md);
    }
  }
  cout << res << "\n";
  return 0;
}

#include <bits/stdc++.h>
using namespace std;
#include <boost/multiprecision/cpp_int.hpp>
using namespace boost::multiprecision;

int main(){
    using F = cpp_int;
    int N, ans = 0;
    cin >> N;
    vector<F> A(N);
    unordered_map<F, int> m;
    for(int i = 0; i < N; i++) cin >> A[i], m[A[i]]++;
    for(F a: A) for(F b: A){
        F tmp = a * b;
        if(m.count(tmp)) ans += m[tmp];
    }
    cout << ans << "\n";
}

#include <bits/stdc++.h>
using namespace std;
#include <boost/multiprecision/cpp_int.hpp>
using namespace boost::multiprecision;

int main(){
    using F = cpp_int;
    int N, ans = 0;
    cin >> N;
    vector<F> A(N);
    unordered_map<F, int> m;
    for(int i = 0; i < N; i++) cin >> A[i], m[A[i]]++;
    sort(A.begin() , A.end()); // ソートしておく
    for(F a: A) for(F b: A){
        F tmp = a * b;
        if(tmp > A[N - 1]) break; // これ以上 j を増やす必要はない
        if(m.count(tmp)) ans += m[tmp];
    }
    cout << ans << "\n";
}
